// 1. Obtenemos los productos del nodo anterior
const inputData = $input.first().json;
const todosLosProductos = inputData.productos || inputData.json || [inputData]; 

// --- CONFIGURACIÓN ---
const LIMITE = 5; // Cambia este número para mostrar más o menos productos
// ---------------------

const mostrar = todosLosProductos.slice(0, LIMITE);
const restantes = todosLosProductos.length - LIMITE;

let mensaje = `📋 *Catálogo de Productos (${todosLosProductos.length} totales)*\n\n`;

mostrar.forEach((prod, index) => {
  mensaje += `📦 *Ítem #${index + 1}*\n`;

  for (const llave in prod) {
    if (llave === 'pairedItem') continue;

    let valor = prod[llave];
    let titulo = llave.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());

    if (Array.isArray(valor)) {
      mensaje += `📍 *${titulo}:*\n`;
      valor.forEach(v => {
        mensaje += (typeof v === 'object') 
          ? `   • ${Object.values(v).join(' - ')}\n` 
          : `   • ${v}\n`;
      });
    } else {
      const display = (valor !== null && typeof valor === 'object')
        ? Object.values(valor).join(' ')
        : (valor ?? '');
      mensaje += `📍 *${titulo}:* ${display}\n`;
    }
  }
  mensaje += `\n──────────────────\n\n`;
});

// 2. Si hay más productos, añadimos el "etc..."
if (restantes > 0) {
  mensaje += `➕ *... y otros ${restantes} productos más.*\n\n`;
  mensaje += `👉 _Escribe 'Ver todo' o contacta a un asesor para el catálogo completo._`;
}

return { mensaje_final: mensaje };

const rawText = $input.first().json.content.parts[0].text;

try {
  // Remove markdown fences
  let clean = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

  // Extract only the JSON portion (from first [ or { to last ] or })
  const arrStart = clean.indexOf('[');
  const arrEnd   = clean.lastIndexOf(']');
  const objStart = clean.indexOf('{');
  const objEnd   = clean.lastIndexOf('}');

  if (arrStart !== -1 && arrEnd !== -1 && (arrStart < objStart || objStart === -1)) {
    clean = clean.substring(arrStart, arrEnd + 1);
  } else if (objStart !== -1 && objEnd !== -1) {
    clean = clean.substring(objStart, objEnd + 1);
  }

  const parsed = JSON.parse(clean);

  let productos;
  let prompt_injection_detectado = false;
  let texto_sospechoso = null;

  if (parsed && !Array.isArray(parsed) && typeof parsed === 'object' && Array.isArray(parsed.productos)) {
    // Formato nuevo: objeto con { productos, prompt_injection_detectado, texto_sospechoso }
    productos = parsed.productos;
    prompt_injection_detectado = parsed.prompt_injection_detectado === true;
    texto_sospechoso = parsed.texto_sospechoso || null;
  } else {
    // Formato viejo: array plano de productos (compatibilidad hacia atras)
    productos = Array.isArray(parsed) ? parsed : [parsed];
  }

  return [{ json: { productos, prompt_injection_detectado, texto_sospechoso } }];

} catch (error) {
  return [{ json: { error: 'Error al parsear', raw: rawText } }];
}

// Fix bug watermark (D12): convierte a base64 la imagen LIMPIA (sin marca de agua) que
// acaba de salir de 'Generate an image' o 'Edit an image', ANTES de que 'Watermark IA' la
// marque, para poder guardarla y usarla como fuente si el usuario pide 'rehacer'.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64 = buffer.toString('base64');

return [
  {
    json: {
      imagen_raw_b64: base64
    }
  }
];

// Fix bug watermark: reconstruye la imagen LIMPIA (sin marca de agua) desde el base64
// guardado en Redis ('imagen_raw_{chat_id}') para que 'Edit an image' edite la version
// original de Gemini, no la que ya tiene watermark. Antes se usaba 'Get a file1'
// (borrado), que descargaba de Telegram la foto YA marcada mostrada al usuario, causando
// que cada 'rehacer' aplicara un watermark duplicado/distorsionado sobre otro watermark.
const base64 = $input.first().json.imagen_raw_b64;
const buffer = Buffer.from(base64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'imagen_raw.png', 'image/png');

return [
  {
    json: $input.first().json,
    binary: {
      data: binaryData
    }
  }
];

const items = $input.all();
const productos = items.map(item => item.json);
const chatId = $('Telegram Trigger').first().json.message.chat.id;

const mensajes = [];

if (productos.length === 1 && productos[0]._parse_failed) {
  // Bug encontrado 2026-08-19: antes esto caia en el forEach de abajo y mostraba
  // "undefined" en todos los campos en vez de avisar que la lectura fallo.
  mensajes.push("⚠️ No pudimos leer los productos de ese archivo/enlace correctamente. Probá de nuevo o revisá el link/formato de la hoja.");
} else {
  // Cambiamos el encabezado para que sea más claro
  let buffer = "🚀 *He analizado tu archivo. Aquí tienes algunos de los productos detectados:* \n\n";

  productos.forEach((prod, index) => {
      let detalle = `📱 *${prod["nombre del producto"]}* \n` +
                    `💰 *Precio:* ${prod["precio"]} \n` +
                    `📝 *Descripción:* ${prod["descripcion"] || prod["descripción"] || ""} \n` +
                    `────────────────── \n\n`;

      if (buffer.length + detalle.length > 3500) {
          mensajes.push(buffer);
          buffer = "";
      }
      buffer += detalle;
  });

  // Agregamos una nota aclaratoria al final del último mensaje
  buffer += "✨ _(Nota: Esta es una muestra de la información leída. El resto de los datos ya han sido guardados correctamente en el sistema)_";
  mensajes.push(buffer);
}

// Retornamos el array con el id_chat incluido en cada ítem
return mensajes.map(msg => ({
    json: {
        mensaje_final: msg,
        id_chat: chatId
    }
}));

const input = $input.first().json;



// 1. Verificamos si es un clic en un botón (Callback Query)

if (input.callback_query) {

  return [

    {

      json: {
        id_chat: input.callback_query.message.chat.id,
        id_mensaje: input.callback_query.message.message_id.toString()
      }

    }

  ];

}



// 2. Verificamos si es un mensaje de texto normal

if (input.message && input.message.text) {

  return [

    {

      json: {
        id_chat: input.message.chat.id,
        id_mensaje: input.message.message_id.toString()
      }

    }

  ];

}



if (input.message.photo) {

  return [

    {

      json: {
        id_chat: input.message.chat.id,
        id_mensaje: input.message.message_id.toString()
      }

    }

  ]

}
if (input.message.document) {

  return [

    {

      json: {
        id_chat: input.message.chat.id,
        id_mensaje: input.message.message_id.toString(),
        id_pdf: input.message.document.file_id
      }

    }

  ]

}

if (input.message.video) {

  return [

    {

      json: {
        id_chat: input.message.chat.id,
        id_mensaje: input.message.message_id.toString()
      }

    }

  ]

}

// Fallback: cualquier otro tipo de mensaje no contemplado arriba (voice, sticker,
// location, etc.) igual devuelve id_chat/id_mensaje en vez de morir sin retornar
// items (bug real: un video colgaba el bot en silencio porque esta funcion no
// tenia ningun return para ese caso).
if (input.message) {

  return [

    {

      json: {
        id_chat: input.message.chat.id,
        id_mensaje: input.message.message_id.toString()
      }

    }

  ]

}

const rawText =  $input.first().json.content.parts[0].text;// O la propiedad donde Gemini escupa el texto
// Limpiamos las marcas de markdown si existen
const cleanJson = rawText.replace(/```json|```/g, "").trim();
const parsed = JSON.parse(cleanJson);

// image-injection-gate (2026-08-23): separamos los datos del producto de la
// señal de injection -- 'IF - Prompt injection detectado - Imagen' usa
// prompt_injection_detectado, y 'Preparar pendientes - Imagen' descarta estos
// 2 campos antes de armar el item que se sube al catalogo.
return {
  producto: parsed.producto,
  precio: parsed.precio,
  detalle: parsed.detalle,
  prompt_injection_detectado: parsed.prompt_injection_detectado === true,
  texto_sospechoso: typeof parsed.texto_sospechoso === 'string' ? parsed.texto_sospechoso.slice(0, 300) : null
};

// 1. Capturamos el evento (boton o mensaje) y el estado de Redis
const rawInput = $('Telegram Trigger').first().json;
const dataRedis = $("Redis27").first().json.informacion_chat;

let estadoChat = "";
let ultimoMensajeId = "";

// 2. Extraccion ultra-segura del Estado y del Ultimo Mensaje usando Regex
if (dataRedis) {
    if (typeof dataRedis === 'object') {
        estadoChat = dataRedis.estado_de_chat || "";
        ultimoMensajeId = dataRedis.ultimo_mensaje || "";
    } else if (typeof dataRedis === 'string') {
        // 🔍 Buscamos quirurgicamente "estado_de_chat"
        const matchEstado = dataRedis.match(/"estado_de_chat"\s*:\s*"([^"]+)"/);
        if (matchEstado && matchEstado[1]) {
            estadoChat = matchEstado[1].trim();
        }

        // 🔍 Buscamos quirurgicamente "ultimo_mensaje" (ej: "24" u "85")
        const matchMensaje = dataRedis.match(/"ultimo_mensaje"\s*:\s*"([^"]+)"/);
        if (matchMensaje && matchMensaje[1]) {
            ultimoMensajeId = matchMensaje[1].trim();
        } else {
            // Fallback secundario si por alguna razon viene sin comillas (numerico puro)
            const matchMensajeNum = dataRedis.match(/"ultimo_mensaje"\s*:\s*([0-9]+)/);
            if (matchMensajeNum && matchMensajeNum[1]) {
                ultimoMensajeId = matchMensajeNum[1].trim();
            }
        }
    }
}

// Extraemos los datos del trigger de entrada (por si los necesitas para el chat_id)
const isBoton = !!rawInput.callback_query;
// isFoto/isVideo (task 6.2): detectan publicidad existente (foto o video, incluye
// message.document con mime_type de imagen/video). NO reemplazan la semantica de
// ESPERANDO IMAGENES (D2b): esa rama sigue evaluandose primero y solo mira
// message.photo puro, ver bloque 4 mas abajo.
const isVideo = !!rawInput.message?.video || (rawInput.message?.document?.mime_type || '').startsWith('video/');
const isFoto = !!rawInput.message?.photo || (rawInput.message?.document?.mime_type || '').startsWith('image/');
const contenido = isBoton ? rawInput.callback_query.data : rawInput.message?.text;
const chatId = isBoton ? rawInput.callback_query.message.chat.id : rawInput.message.chat.id;

let resultadoFinal = "Acciones no permitidas";

// --- LOGICA DE DECISION DE RUTAS ---

// CONTROL DE PRIMERA INTERACCION
if (!estadoChat) {
    resultadoFinal = "Inicio";
} 
// 2. Si el bot espera un boton pero el usuario envia texto plano o foto
else if (!isBoton && !isFoto && (
    estadoChat === "ESPERANDO RESPUESTA" || 
    estadoChat === "ESPERANDO RESPUESTA SOBRE OPCIONES DE SUBIR INFORMACION" || 
    estadoChat === "ESPERANDO APROBACION" || 
    estadoChat === "ESPERANDO RESPUESTA SOBRE IMAGEN"
)) {
    resultadoFinal = "Acciones no permitidas";
}
// 3. Reglas de botones
else if (isBoton) {
    if (contenido && contenido.startsWith("sched:") && estadoChat === "ESPERANDO PROGRAMACION") {resultadoFinal = "Programacion";}
    else if (contenido && contenido.startsWith("plat:") && estadoChat === "ESPERANDO SELECCION PLATAFORMAS") {resultadoFinal = "Toggle plataforma";}
    else if (contenido === "plat_ok" && estadoChat === "ESPERANDO SELECCION PLATAFORMAS") {resultadoFinal = "Confirmar plataformas";}
    else if (contenido === "confirmar_upsert" && estadoChat === "ESPERANDO CONFIRMACION SOBRESCRITURA") {resultadoFinal = "Confirmar sobrescritura";}
    else if (contenido === "cancelar_upsert" && estadoChat === "ESPERANDO CONFIRMACION SOBRESCRITURA") {resultadoFinal = "Cancelar sobrescritura";}
    else if (contenido === "Inicio") {resultadoFinal = "Inicio";}
    else if (contenido === "Cargar informacion" && estadoChat === "ESPERANDO RESPUESTA") {resultadoFinal = "Subir informacion";}
    else if (contenido === "Generar publicidad" && estadoChat === "ESPERANDO RESPUESTA") {resultadoFinal = "Generar publicidad";}
    else if (contenido === "Subir publicidad existente" && estadoChat === "ESPERANDO RESPUESTA") {resultadoFinal = "Pedir publicidad existente";}
    else if (contenido === "Google Sheets" && estadoChat === "ESPERANDO RESPUESTA SOBRE OPCIONES DE SUBIR INFORMACION") {resultadoFinal = "Google sheet";}
    else if (contenido === "Imagenes" && estadoChat === "ESPERANDO RESPUESTA SOBRE OPCIONES DE SUBIR INFORMACION") {resultadoFinal = "Imagen";}
    else if (contenido === "PDF" && estadoChat === "ESPERANDO RESPUESTA SOBRE OPCIONES DE SUBIR INFORMACION") {resultadoFinal = "PDF";}
    else if (contenido === "Dar especificaciones" && estadoChat === "ESPERANDO INFORMACION SOBRE ESPECIFICACIONES") {resultadoFinal = "Dar especificaciones";}
    else if (contenido === "Generar publicidad sin especificacion" && estadoChat === "ESPERANDO INFORMACION SOBRE ESPECIFICACIONES") {resultadoFinal = "Sin badges";}
    else if (contenido === "Aprobado" && estadoChat === "ESPERANDO APROBACION") {resultadoFinal = "Aprobado";}
    else if (contenido === "Rechazado" && estadoChat === "ESPERANDO APROBACION") {resultadoFinal = "Rechazado";}
    else if (contenido === "Agregar foto" && estadoChat === "ESPERANDO RESPUESTA SOBRE IMAGEN") {resultadoFinal = "Agregar foto";}
    else if (contenido === "No agregar foto" && estadoChat === "ESPERANDO RESPUESTA SOBRE IMAGEN") {resultadoFinal = "No agregar foto";}
    else if (contenido === "Sin descripcion" && estadoChat === "ESPERANDO DESCRIPCION") {resultadoFinal = "Sin descripcion";}
}
// 4. Reglas para fotos y video (catalogo de producto + publicidad existente)
// D2b: message.photo tiene DOS semanticas segun estado. La de ESPERANDO IMAGENES
// (foto de referencia del producto, sin moderar, sin publicar) se evalua PRIMERO
// y conserva su comportamiento exacto (isFoto puro, sin isVideo). Solo si no aplica
// esa rama se evalua la de publicidad existente (foto O video).
else if (isFoto || isVideo) {
    if (estadoChat === "ESPERANDO IMAGENES" && !!rawInput.message?.photo) {
        resultadoFinal = "Imagen de informacion";
    } else if (estadoChat === "ESPERANDO PUBLICIDAD EXISTENTE") {
        resultadoFinal = "Publicidad existente";
    }
    // cualquier otro estado no contemplado deja resultadoFinal en su default
    // ("Acciones no permitidas")
}
// 5. Reglas para texto plano
else {
    if (estadoChat === "ESPERANDO INFORMACION SOBRE ESPECIFICACIONES") {
        resultadoFinal = "Especificaciones";
    } else if (estadoChat === "ESPERANDO DESCRIPCION") {
        resultadoFinal = "Descripcion";
    } else if (estadoChat === "ESPERANDO ESPECIFICACION PARA REHACER") {
        resultadoFinal = "Especificaciones para rehacer";
    } else if (estadoChat === "ESPERANDO LINK DE GOOGLE SHEET" && contenido?.toLowerCase().includes("docs.google.com")) {
        resultadoFinal = "Link";
    } else if (estadoChat === "ESPERANDO PDF") {
        resultadoFinal = "Analizar PDF";
    } else if (estadoChat === "ESPERANDO FECHA PERSONALIZADA") {
        resultadoFinal = "Fecha personalizada";
    } else {
        resultadoFinal = "Acciones no permitidas";
    }
}

return {
    json: {
        id_chat: chatId,
        id_mensaje: ultimoMensajeId,
        estadoChat: estadoChat, // <--- Aqui devuelve limpiamente el ID guardado en Redis (Ej: "24" u "85")
        tipo: isBoton ? "Boton" : (isVideo ? "Video" : (isFoto ? "Imagen" : "Texto")),
        resultado: resultadoFinal,
        dato: contenido
    }
};

