// 1. Obtenemos todos los ítems
const inputItems = $input.all();

// 2. BUSCAMOS EL VALOR: 
// En lugar de 'json.result', sacamos el primer valor que venga en el JSON
const data = inputItems[0].json;
const nombreDeLaKey = Object.keys(data)[0]; // Esto detecta "fotos_6421800770"
const cantidadDeFotos = parseInt(data[nombreDeLaKey]) || 0;

// 3. Si es 0, aviso
if (cantidadDeFotos === 0) {
  return [{ json: { error: "No hay fotos", debug_recibido: data } }];
}

let listaParaBucle = [];

// 4. Generamos la lista
for (let i = 0; i < cantidadDeFotos; i++) {
  listaParaBucle.push({
    json: {
      vuelta: i + 1,
      total: cantidadDeFotos,
      instruccion: "pedir_foto_a_redis"
    }
  });
}

return listaParaBucle;

const { spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const crypto = require('crypto');

const logoBase64 = "";
const logoBuffer = Buffer.from(logoBase64, 'base64');
const LOGO_SIZE = 170;
const BACKING_RADIUS = 100;
const BACKING_COLOR = 'rgba(0,0,0,0.55)';

const items = $input.all();
const returnData = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const width = item.json.size.width;
  const height = item.json.size.height;
  const posX = Math.round(width - LOGO_SIZE);
  const posY = Math.round(height - LOGO_SIZE);
  const geometry = (posX >= 0 ? '+' : '') + posX + (posY >= 0 ? '+' : '') + posY;

  const cx = Math.round(width - LOGO_SIZE / 2);
  const cy = Math.round(height - LOGO_SIZE / 2);
  const circleDraw = `circle ${cx},${cy} ${cx},${cy - BACKING_RADIUS}`;

  const logoPath = path.join(os.tmpdir(), `wm-logo-${crypto.randomUUID()}.png`);
  const backingPath = path.join(os.tmpdir(), `wm-backing-${crypto.randomUUID()}.png`);
  fs.writeFileSync(logoPath, logoBuffer);

  try {
    const imageBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');

    // Paso 1: respaldo circular (no cuadrado) semitransparente detras del logo, para que
    // se vea como una etiqueta redonda en vez de un recuadro. No cubre el 100% de la zona
    // de 220x220 que la prompt le pide a Gemini que evite (un circulo no llega a las
    // esquinas de un cuadrado) -- decision consciente: se prioriza que se vea como
    // etiqueta chica en vez de tapar cualquier cosa que Gemini dibuje ahi.
    const backingResult = spawnSync('gm', ['convert', '-', '-fill', BACKING_COLOR, '-draw', circleDraw, backingPath], {
      input: imageBuffer,
      maxBuffer: 50 * 1024 * 1024,
    });
    if (backingResult.status !== 0) {
      const stderrText = backingResult.stderr ? backingResult.stderr.toString() : 'sin salida de error';
      throw new Error(`gm convert (respaldo) fallo (exit ${backingResult.status}): ${stderrText}`);
    }

    // Paso 2: compone el logo sobre el respaldo. Dos comandos gm separados porque
    // encadenar draw+page+flatten en un solo comando produce resultados inconsistentes
    // en esta version de GraphicsMagick (verificado).
    const result = spawnSync('gm', ['convert', backingPath, '-page', geometry, logoPath, '-flatten', '-'], {
      maxBuffer: 50 * 1024 * 1024,
    });
    if (result.status !== 0 || !result.stdout || result.stdout.length === 0) {
      const stderrText = result.stderr ? result.stderr.toString() : 'sin salida de error';
      throw new Error(`gm convert (logo) fallo (exit ${result.status}): ${stderrText}`);
    }

    const binaryData = await this.helpers.prepareBinaryData(result.stdout, 'ad-watermarked.png', 'image/png');
    returnData.push({ json: item.json, binary: { data: binaryData } });
  } finally {
    fs.unlinkSync(logoPath);
    if (fs.existsSync(backingPath)) fs.unlinkSync(backingPath);
  }
}

return returnData;

const rawText = $input.first().json.output ?? $input.first().json.text;
const idChat = (() => { try { return $('Code in JavaScript5').first().json.id_chat; } catch (e) { return null; } })();

function fail(motivo) {
  return [ { json: { _parse_failed: true, motivo, raw: String(rawText).slice(0, 500) } } ];
}

try {
  // sheets-injection-gate (2026-08-23): probamos primero el formato objeto nuevo
  // ({productos, prompt_injection_detectado, texto_sospechoso} -- mismo contrato que
  // "Analyze document" para PDF). Si no matchea, caemos al formato array plano legado
  // (rama "AI Agent1", sin cambios de comportamiento para esa rama).
  const objMatch = String(rawText).match(/\{[\s\S]*\}/);
  if (objMatch) {
    let obj = null;
    try { obj = JSON.parse(objMatch[0]); } catch (e) { obj = null; }
    if (obj && Array.isArray(obj.productos)) {
      const validosObj = obj.productos.filter((item) => item && typeof item === 'object' && item['nombre del producto']);

      if (obj.prompt_injection_detectado === true) {
        // partial-success (2026-08-23, pedido del usuario): antes esto descartaba
        // los productos y devolvia SOLO el marcador de injection (bloqueaba todo
        // el lote). El prompt ya le exige al modelo "detectar y reportar, nunca
        // cumplir" la instruccion inyectada -- si dice que detecto injection es
        // porque la resistio y los productos extraidos siguen siendo confiables.
        // Ahora: se manda el marcador (dispara UNA alerta al admin via el IF de
        // abajo, no se sube como producto) MAS los productos validos (que el
        // mismo IF deja pasar a la carga normal, por no tener _injection_detected).
        const marcador = {
          json: {
            _injection_detected: true,
            idChat,
            texto_sospechoso: typeof obj.texto_sospechoso === 'string' ? obj.texto_sospechoso.slice(0, 300) : null,
            // bugfix (2026-08-23): si no hay NINGUN producto valido junto al
            // marcador, el resto de la cadena (confirmacion) nunca corre y el
            // usuario se queda sin respuesta -- este flag dispara un aviso
            // dedicado. Si SI hay productos, el mensaje de confirmacion normal
            // ya le responde al usuario, no se duplica.
            sinProductosValidos: validosObj.length === 0
          }
        };
        const productosValidos = validosObj.map((item) => ({ json: { ...item, _injection_detected: false } }));
        return [marcador, ...productosValidos];
      }

      if (validosObj.length === 0) {
        return fail('Ningun item de "productos" tiene el campo "nombre del producto"');
      }
      return validosObj.map((item) => ({ json: item }));
    }
  }

  // 1. Extraemos el bloque JSON real aunque el modelo haya agregado texto antes/despues
  //    o lo haya envuelto en fences de markdown. Antes solo se quitaban las fences
  //    (```json ... ```), y un parrafo de prosa antes/despues del array rompia el
  //    JSON.parse -- caia al catch y ese objeto de error terminaba subido como si fuera
  //    un producto real (bug encontrado 2026-08-19, corrompio el catalogo real dos veces).
  const match = String(rawText).match(/\[[\s\S]*\]/);
  if (!match) {
    return fail('No se encontro un array JSON en la respuesta del modelo');
  }
  const data = JSON.parse(match[0]);

  if (!Array.isArray(data) || data.length === 0) {
    return fail('El JSON parseado no es un array con al menos un producto');
  }

  // 2. Nunca dejamos pasar un item sin nombre de producto hacia el upsert -- validacion
  //    minima de forma para que basura no llegue a Supabase como si fuera un producto.
  const validos = data.filter((item) => item && typeof item === 'object' && item['nombre del producto']);
  if (validos.length === 0) {
    return fail('Ningun item tiene el campo "nombre del producto"');
  }

  return validos.map((item) => ({ json: item }));

} catch (error) {
  return fail('JSON.parse fallo: ' + error.message);
}

