// Lee la lista de integraciones cacheada (integraciones_{chat_id}, seteada en
// "Preparar teclado plataformas" / "Redis - Guardar integraciones" al entrar a
// la etapa de selección de plataformas) en vez de volver a golpear la API en
// vivo: garantiza que los índices de "plataformas_{chat_id}" (elegidos por el
// usuario contra ESA lista exacta) sigan siendo válidos al armar postsArray.
let lista = [];
try {
  lista = JSON.parse($('Redis - Get integraciones').first().json.integraciones_raw || '[]');
} catch (e) {
  lista = [];
}

const withIntegration = lista.filter(a => a.postiz_integration_id);

if (withIntegration.length === 0) {
  return [{ json: { hasIntegrations: false, postsArray: [] } }];
}

let seleccion = [];
try {
  seleccion = JSON.parse($json.plataformas_raw || '[]');
} catch (e) {
  seleccion = [];
}
if (!Array.isArray(seleccion)) seleccion = [];

// Fallback (D4 / task 5.10): sin selección o clave expirada -> todas las cuentas.
const elegidas = seleccion.length > 0
  ? withIntegration.filter(a => seleccion.includes(a.idx))
  : withIntegration;

const settingsMap = {
  instagram: { __type: 'instagram', post_type: 'post' },
  facebook:  { __type: 'facebook',  post_type: 'post' },
};

const postsArray = elegidas.map(acc => ({
  integration: { id: acc.postiz_integration_id },
  settings: settingsMap[acc.platform_type] || { __type: acc.platform_type, post_type: 'post' },
  value: [{ content: 'placeholder', image: [] }]
}));

return [{ json: { hasIntegrations: true, postsArray } }];

// Resuelve los botones rápidos de programación (sched:now|1h|hoy20|man09) a
// { tipo: 'now'|'schedule', fechaISO: <UTC ISO 8601> }.
// sched:custom NO llega a este nodo: se desvía antes, en "IF - Fecha personalizada
// elegida", hacia el flujo de fecha personalizada ("Parsear fecha personalizada").
//
// Conversión de horario: se usa Intl.DateTimeFormat con timeZone
// 'America/Argentina/Buenos_Aires' para leer/escribir hora de pared en BA de forma
// robusta ante cualquier cambio futuro de política horaria (Argentina no aplica DST
// desde 2009, así que hoy equivale a un offset fijo de -180 min). Si Intl fallara en
// el runtime, se cae al offset fijo documentado como fallback (D5 de design.md).
const TZ = 'America/Argentina/Buenos_Aires';
const TZ_OFFSET_MIN_FALLBACK = -180; // UTC-3 fijo (fallback si Intl no está disponible)

function offsetMinutesAt(date) {
  try {
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: TZ, hour12: false,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
    const parts = dtf.formatToParts(date).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
    const hour = parts.hour === '24' ? '00' : parts.hour;
    const asUTC = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +hour, +parts.minute, +parts.second);
    return (asUTC - date.getTime()) / 60000;
  } catch (e) {
    return TZ_OFFSET_MIN_FALLBACK;
  }
}

function baWallTimeParts(date) {
  try {
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: TZ, hour12: false,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
    const parts = dtf.formatToParts(date).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
    return {
      year: +parts.year, month: +parts.month, day: +parts.day,
      hour: parts.hour === '24' ? 0 : +parts.hour, minute: +parts.minute, second: +parts.second
    };
  } catch (e) {
    const utcMs = date.getTime() + TZ_OFFSET_MIN_FALLBACK * 60000;
    const d = new Date(utcMs);
    return {
      year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate(),
      hour: d.getUTCHours(), minute: d.getUTCMinutes(), second: d.getUTCSeconds()
    };
  }
}

// Convierte una hora de pared en BA (year,month,day,hour,minute) a un Date UTC correcto.
// Date.UTC normaliza automáticamente overflow de día/mes (ej: day = 32 en enero -> 1 feb).
function baWallToUTC(year, month, day, hour, minute) {
  const naiveUTC = Date.UTC(year, month - 1, day, hour, minute, 0);
  const offsetMin = offsetMinutesAt(new Date(naiveUTC));
  return new Date(naiveUTC - offsetMin * 60000);
}

const dato = $input.first().json.dato;
const ahora = new Date();
const hoyBA = baWallTimeParts(ahora);

let tipo = 'now';
let fecha = ahora;

if (dato === 'sched:now') {
  tipo = 'now';
  fecha = ahora;
} else if (dato === 'sched:1h') {
  tipo = 'schedule';
  fecha = new Date(ahora.getTime() + 60 * 60 * 1000);
} else if (dato === 'sched:hoy20') {
  tipo = 'schedule';
  fecha = baWallToUTC(hoyBA.year, hoyBA.month, hoyBA.day, 20, 0);
  // Si las 20:00 de hoy ya pasaron (o quedan menos de 5 min), se corre a mañana.
  if (fecha.getTime() - ahora.getTime() < 5 * 60 * 1000) {
    fecha = baWallToUTC(hoyBA.year, hoyBA.month, hoyBA.day + 1, 20, 0);
  }
} else if (dato === 'sched:man09') {
  tipo = 'schedule';
  fecha = baWallToUTC(hoyBA.year, hoyBA.month, hoyBA.day + 1, 9, 0);
} else {
  // Fallback defensivo: no debería llegar acá (ver IF - Fecha personalizada elegida).
  tipo = 'now';
  fecha = ahora;
}

return {
  json: {
    tipo,
    fechaISO: fecha.toISOString()
  }
};

// Parsea la fecha personalizada ingresada como texto libre en formato
// DD/MM/AAAA HH:MM (hora local Argentina), valida que sea futura (mínimo +5 min)
// y la convierte a UTC ISO 8601. Reutiliza la misma conversión de zona horaria que
// "Calcular fecha publicacion" (Intl.DateTimeFormat con fallback de offset fijo -180).
const TZ = 'America/Argentina/Buenos_Aires';
const TZ_OFFSET_MIN_FALLBACK = -180;

function offsetMinutesAt(date) {
  try {
    const dtf = new Intl.DateTimeFormat('en-US', {
      timeZone: TZ, hour12: false,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit'
    });
    const parts = dtf.formatToParts(date).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
    const hour = parts.hour === '24' ? '00' : parts.hour;
    const asUTC = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +hour, +parts.minute, +parts.second);
    return (asUTC - date.getTime()) / 60000;
  } catch (e) {
    return TZ_OFFSET_MIN_FALLBACK;
  }
}

function baWallToUTC(year, month, day, hour, minute) {
  const naiveUTC = Date.UTC(year, month - 1, day, hour, minute, 0);
  const offsetMin = offsetMinutesAt(new Date(naiveUTC));
  return new Date(naiveUTC - offsetMin * 60000);
}

const texto = (($input.first().json.dato) || '').trim();

// Formato estricto DD/MM/AAAA HH:MM
const match = texto.match(/^([0-3]\d)\/([0-1]\d)\/(\d{4})\s+([0-2]\d):([0-5]\d)$/);

if (!match) {
  return { json: { valido: false, motivo: 'formato', textoOriginal: texto } };
}

const day = +match[1];
const month = +match[2];
const year = +match[3];
const hour = +match[4];
const minute = +match[5];

// Validación de rango real de calendario (evita 31/02, 00/13, hora 25, etc.)
const rangoOk = month >= 1 && month <= 12 && day >= 1 && day <= 31 && hour <= 23 && minute <= 59;
if (!rangoOk) {
  return { json: { valido: false, motivo: 'formato', textoOriginal: texto } };
}

const fechaUTC = baWallToUTC(year, month, day, hour, minute);

// Chequeo de que el día/mes ingresado exista de verdad (Date.UTC normaliza overflow,
// por eso se recalculan los componentes en BA a partir del resultado y se comparan
// con lo pedido: si no coinciden, la fecha no existía -> formato inválido).
let normalizado;
try {
  const dtf = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit'
  });
  const parts = dtf.formatToParts(fechaUTC).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
  normalizado = { year: +parts.year, month: +parts.month, day: +parts.day };
} catch (e) {
  normalizado = { year, month, day };
}
if (normalizado.year !== year || normalizado.month !== month || normalizado.day !== day) {
  return { json: { valido: false, motivo: 'formato', textoOriginal: texto } };
}

const ahora = new Date();
if (fechaUTC.getTime() - ahora.getTime() < 5 * 60 * 1000) {
  return { json: { valido: false, motivo: 'pasado', textoOriginal: texto } };
}

return {
  json: {
    valido: true,
    tipo: 'schedule',
    fechaISO: fechaUTC.toISOString()
  }
};

// HTTP - Crear post Postiz devuelve un item por plataforma publicada
// (array de posts creados). Sin este colapso, todo lo que sigue (mensaje de
// exito + menu principal) se dispara una vez por plataforma -> mensajes
// duplicados en Telegram.
return [{ json: { postsCreados: $input.all().length } }];

// A partir de la salida de "HTTP - Cuenta Instagram publicacion" (filas de
// social_accounts con postiz_integration_id no nulo), arma:
//  - la lista indexada (persistida luego en integraciones_{chat_id})
//  - las filas del inline keyboard, todo desmarcado (⬜) al inicio
const accounts = $input.all().map(i => i.json);

const lista = accounts.map((a, idx) => ({
  idx,
  postiz_integration_id: a.postiz_integration_id,
  platform_type: a.platform_type,
  account_id: a.account_id
