const labelMap = { instagram: 'Instagram', facebook: 'Facebook', threads: 'Threads', x: 'X' };

const filas = lista.map(item => ({
  row: {
    buttons: [
      {
        text: `⬜ ${labelMap[item.platform_type] || item.platform_type} — ${item.account_id}`,
        additionalFields: { callback_data: `plat:${item.idx}` }
      }
    ]
  }
}));

filas.push({ row: { buttons: [{ text: '✅ Continuar', additionalFields: { callback_data: 'plat_ok' } }] } });
filas.push({ row: { buttons: [{ text: '🏠 Volver al inicio', additionalFields: { callback_data: 'Inicio' } }] } });

return [{
  json: {
    hasIntegrations: lista.length > 0,
    lista,
    filas
  }
}];

// Toggle de una plataforma: agrega o quita el índice recibido en "dato"
// (formato "plat:<idx>") de la selección vigente, y redibuja el teclado
// completo con ☑️ / ⬜ según corresponda. NO cambia estado_de_chat.
const dato = $('Code in JavaScript5').first().json.dato || '';
const idx = parseInt(String(dato).split(':')[1], 10);

let lista = [];
try {
