    veredicto = {
      apto: parsed.apto,
      categoria: parsed.categoria || 'otro',
      motivo: parsed.motivo || ''
    };
  }
} catch (e) {
  // se conserva el veredicto de rechazo por defecto
}

return [{ json: veredicto }];

