// Validación de firma binaria (magic bytes) — rama PDF.
// capability: binary-signature-validation — openspec/changes/input-security-hardening
// Compara la familia REAL del binario (derivada de sus primeros bytes) contra la
// familia declarada ('pdf', fija en esta rama: solo llega binario acá cuando el router
// ya clasificó el mensaje como PDF). NO reemplaza a 'Escaneo ClamAV' (aguas abajo):
// esto es un control de TIPO, no de malware (design.md D1).
//
// ===================== MODO OBSERVACIÓN / ENFORCEMENT (tasks.md 0.3) =====================
// OBSERVATION_MODE = false  -> detecta y alimenta la alerta al admin, pero NUNCA rechaza.
//                              Arranque obligatorio en este modo (resuelto 2026-08-17)
//                              hasta confirmar con archivos reales de Android/iOS/desktop
//                              que no hay falsos positivos.
// OBSERVATION_MODE = false -> fail-closed real: firma inválida = rechazo, a través de
//                              'IF - Firma PDF válida' (lee magicBytes.observationMode).
//
// PARA PASAR A ENFORCEMENT: cambiar esta constante a `false` ACÁ Y en el nodo
// 'Validar firma media' (los dos deben cambiar juntos, mismo despliegue). No hace falta
// tocar ninguna conexión: los IF de validez ya leen el flag desde el JSON de salida.
const OBSERVATION_MODE = false;

// Tabla de firmas — misma lógica que tests/magic-bytes/detect-family.js, probada de
// forma aislada en tests/magic-bytes/detect-family.test.js ANTES de escribir este nodo
// (task 1.2). Se copia literal acá porque los nodos Code de n8n no pueden hacer
// require() de archivos del repo (sin NODE_FUNCTION_ALLOW_EXTERNAL).
function matchesBytes(buffer, offset, bytes) {
  if (buffer.length < offset + bytes.length) return false;
  for (let i = 0; i < bytes.length; i++) {
    if (buffer[offset + i] !== bytes[i]) return false;
  }
  return true;
}

function detectFamily(buffer) {
  if (buffer.length === 0) return 'unknown';
  if (matchesBytes(buffer, 0, [0x25, 0x50, 0x44, 0x46, 0x2d])) return 'pdf'; // %PDF-
  if (matchesBytes(buffer, 0, [0xff, 0xd8, 0xff])) return 'image'; // JPEG
  if (matchesBytes(buffer, 0, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image'; // PNG
  if (matchesBytes(buffer, 0, [0x47, 0x49, 0x46, 0x38])) return 'image'; // GIF8
  if (matchesBytes(buffer, 0, [0x52, 0x49, 0x46, 0x46]) && matchesBytes(buffer, 8, [0x57, 0x45, 0x42, 0x50])) return 'image'; // RIFF..WEBP
  if (matchesBytes(buffer, 4, [0x66, 0x74, 0x79, 0x70])) return 'video'; // ftyp (ISO-BMFF: MP4/MOV/3GP)
  if (matchesBytes(buffer, 0, [0x1a, 0x45, 0xdf, 0xa3])) return 'video'; // Matroska/WebM
  return 'unknown';
}

const items = $input.all();
const idChat = $('Code in JavaScript5').first().json.id_chat;
const msg = $('Telegram Trigger').first().json.message || {};
const mimeDeclarado = msg.document?.mime_type || 'desconocido';
const declaredFamily = 'pdf';

const salida = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.data) {
    // Binario ilegible: error real de ejecución, no un mismatch de negocio. Con
    // onError: "continueErrorOutput" (propiedad del nodo, no de parameters), esto cae
    // al output de error -> mismo destino de rechazo (fail-closed, design.md D8), SIN
    // excepción por modo observación: un binario ilegible no es "firma sospechosa a
    // confirmar", es un fallo real de la validación misma.
    throw new Error('magic_bytes_binary_unreadable');
  }
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const derivedFamily = detectFamily(buffer);
  const firmaValida = derivedFamily === declaredFamily;

  salida.push({
    json: {
      ...item.json,
      magicBytes: {
        control: 'firma_binaria',
        rama: 'pdf',
        declaredFamily,
        derivedFamily,
        firmaValida,
        observationMode: OBSERVATION_MODE,
        mimeDeclarado,
        idChat
      }
    },
    binary: item.binary
  });
}

return salida;

