// PARA PASAR A ENFORCEMENT: cambiar esta constante a `false` ACÁ Y en el nodo
// 'Validar firma PDF' (los dos deben cambiar juntos, mismo despliegue). No hace falta
// tocar ninguna conexión: los IF de validez ya leen el flag desde el JSON de salida.
const OBSERVATION_MODE = false;

// Misma tabla de firmas que 'Validar firma PDF' / tests/magic-bytes/detect-family.js.
function matchesBytes(buffer, offset, bytes) {
  if (buffer.length < offset + bytes.length) return false;
  for (let i = 0; i < bytes.length; i++) {
    if (buffer[offset + i] !== bytes[i]) return false;
  }
  return true;
}

function detectFamily(buffer) {
  if (buffer.length === 0) return 'unknown';
  if (matchesBytes(buffer, 0, [0x25, 0x50, 0x44, 0x46, 0x2d])) return 'pdf';
  if (matchesBytes(buffer, 0, [0xff, 0xd8, 0xff])) return 'image';
  if (matchesBytes(buffer, 0, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image';
  if (matchesBytes(buffer, 0, [0x47, 0x49, 0x46, 0x38])) return 'image';
  if (matchesBytes(buffer, 0, [0x52, 0x49, 0x46, 0x46]) && matchesBytes(buffer, 8, [0x57, 0x45, 0x42, 0x50])) return 'image';
  if (matchesBytes(buffer, 4, [0x66, 0x74, 0x79, 0x70])) return 'video';
  if (matchesBytes(buffer, 0, [0x1a, 0x45, 0xdf, 0xa3])) return 'video';
  return 'unknown';
}

const items = $input.all();
const tipo = $('Code in JavaScript5').first().json.tipo; // 'Video' | 'Imagen' (u otro, no debería llegar acá)
const declaredFamily = tipo === 'Video' ? 'video' : (tipo === 'Imagen' ? 'image' : 'unknown');
