const msg = $('Telegram Trigger').first().json.message || {};
const mimeDeclarado = msg.document?.mime_type || msg.video?.mime_type || (msg.photo ? 'image (photo, sin mime_type explícito)' : 'desconocido');

const salida = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.data) {
    throw new Error('magic_bytes_binary_unreadable');
  }
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const derivedFamily = detectFamily(buffer);
  // declaredFamily === 'unknown' no debería pasar (el router ya filtró a foto/video),
  // pero si pasa, tratamos como mismatch explícito, nunca como aceptación.
  const firmaValida = declaredFamily !== 'unknown' && derivedFamily === declaredFamily;

  salida.push({
    json: {
      ...item.json,
      magicBytes: {
        control: 'firma_binaria',
        rama: 'media',
        declaredFamily,
        derivedFamily,
        firmaValida,
        observationMode: OBSERVATION_MODE,
        mimeDeclarado,
        idChat
      }
    },
    binary: item.binary
  });
