// Rate limiting por chat_id -- capability bot-rate-limiting (grupo 2, input-security-hardening)
// Deriva chat_id y el/los bucket(s) a consumir DIRECTAMENTE del payload crudo de
// Telegram, sin duplicar el dispatch de 'Code in JavaScript7' (chat.id se lee igual
// desde message o callback_query.message, y no hace falta id_mensaje/id_pdf para
// contar cuota). Ubicacion: inmediatamente despues de 'Telegram Trigger', ANTES de
// 'Code in JavaScript7' -- ver reporte de apply de grupo 2 para la justificacion del
// punto de empalme exacto (splice point).
//
// Esquema de claves (task 2.1): ratelimit:<chat_id>:<bucket>:<ventana>
//   bucket  in {'msg', 'file'}
//   ventana = 'm-' + floor(now/60000)   -> ventana corta, 1 minuto
//           | 'h-' + floor(now/3600000) -> ventana larga, 1 hora
// Un evento de archivo consume 'msg' Y 'file' (2 ventanas c/u = 4 claves).
// Un mensaje de texto/callback consume solo 'msg' (2 claves).
const input = $input.first().json;

const chatIdRaw = input.callback_query
  ? (input.callback_query.message && input.callback_query.message.chat.id)
  : (input.message ? input.message.chat.id : null);

// Telegram siempre manda chat.id como number; DEFAULT_ADMIN_CHAT_ID (env var) llega
// como string. Comparacion explicita como string en ambos lados para evitar el bug
// de coercion de tipos.
const chatId = (chatIdRaw === null || chatIdRaw === undefined) ? null : String(chatIdRaw);
const adminChatIdRaw = $env.DEFAULT_ADMIN_CHAT_ID;
const adminChatId = (adminChatIdRaw === undefined || adminChatIdRaw === null || adminChatIdRaw === '')
  ? null
  : String(adminChatIdRaw);
const esAdmin = adminChatId !== null && chatId !== null && chatId === adminChatId;

// Sin chat_id identificable (update de un tipo no contemplado) -> no se puede armar
// una clave de Redis valida; se deja exento (fail-open acotado a este caso borde, no
// es el fail-open de Redis de 2.7) en vez de arriesgar una clave 'ratelimit:null:...'.
const sinChatId = chatId === null;
const exento = esAdmin || sinChatId;

const esArchivo = !!(input.message && (input.message.document || input.message.photo || input.message.video));

const ahora = Date.now();
const ventanaCorta = 'm-' + Math.floor(ahora / 60000);
const ventanaLarga = 'h-' + Math.floor(ahora / 3600000);

function key(bucket, ventana) {
  return 'ratelimit:' + chatId + ':' + bucket + ':' + ventana;
}

return [{
  json: {
    ...input,
    _rl: {
      chatId,
      esAdmin,
      sinChatId,
      exento,
      esArchivo,
      ventanaCorta,
      ventanaLarga,
      ttlCorta: 60,
      ttlLarga: 3600,
      keyMsgCorta: chatId ? key('msg', ventanaCorta) : null,
      keyMsgLarga: chatId ? key('msg', ventanaLarga) : null,
      keyFileCorta: chatId ? key('file', ventanaCorta) : null,
      keyFileLarga: chatId ? key('file', ventanaLarga) : null
    }
  }
}];

// Evalua las cuotas de rate limit (task 2.4) contra los contadores incrementados
// por los nodos 'Redis - RL incr *'. Lee cada contador por NOMBRE DE NODO con
// .first() -- NUNCA $json ni .item -- porque la operacion 'incr' del nodo Redis de
// n8n NO propaga pairedItem (verificado en el codigo fuente del nodo), asi que
// '.item' rompe la trazabilidad aguas abajo de un nodo Redis 'incr'. .first() no
// depende de pairedItem y es el mismo patron ya usado en 'Validar firma PDF'
// ($('Code in JavaScript5').first().json.id_chat).
const rl = $('Clasificar evento para rate limit').first().json._rl;

const QUOTA_MSG_CORTA = 20;
const QUOTA_MSG_LARGA = 200;
const QUOTA_FILE_CORTA = 5;
const QUOTA_FILE_LARGA = 30;

function valorDe(item) {
  const vals = Object.values(item); // { "<key redis>": <valor incrementado> }
  return vals.length ? Number(vals[0]) : 0;
}

const msgCorta = valorDe($('Redis - RL incr msg corta').first().json);
const msgLarga = valorDe($('Redis - RL incr msg larga').first().json);

let fileCorta = 0;
let fileLarga = 0;
if (rl.esArchivo) {
  fileCorta = valorDe($('Redis - RL incr file corta').first().json);
  fileLarga = valorDe($('Redis - RL incr file larga').first().json);
}

const excedeMsgCorta = msgCorta > QUOTA_MSG_CORTA;
const excedeMsgLarga = msgLarga > QUOTA_MSG_LARGA;
const excedeFileCorta = rl.esArchivo && fileCorta > QUOTA_FILE_CORTA;
const excedeFileLarga = rl.esArchivo && fileLarga > QUOTA_FILE_LARGA;

const dentroDeCuota = !excedeMsgCorta && !excedeMsgLarga && !excedeFileCorta && !excedeFileLarga;

// Ventana que disparo el exceso: prioridad a la ventana corta (la mas restrictiva /
// la primera en dispararse ante un abuso real); si solo se excedio la ventana larga,
// se usa esa. El aviso unico por ventana (task 2.5) queda atado a la ventana que
// efectivamente disparo el exceso.
let ventanaExcedida = null;
let ttlExcedida = null;
if (excedeMsgCorta || excedeFileCorta) {
  ventanaExcedida = rl.ventanaCorta;
  ttlExcedida = rl.ttlCorta;
} else if (excedeMsgLarga || excedeFileLarga) {
  ventanaExcedida = rl.ventanaLarga;
  ttlExcedida = rl.ttlLarga;
}

const keyNotified = ventanaExcedida ? ('ratelimit:' + rl.chatId + ':notified:' + ventanaExcedida) : null;

return [{
  json: {
    ...$('Clasificar evento para rate limit').first().json,
    _rlEval: {
      msgCorta, msgLarga, fileCorta, fileLarga,
      excedeMsgCorta, excedeMsgLarga, excedeFileCorta, excedeFileLarga,
      dentroDeCuota,
      ventanaExcedida,
      ttlExcedida,
      keyNotified
    }
  }
}];

// Fail-open acotado del rate limiter (task 2.7, design.md D2/D8): si cualquiera de
// los nodos Redis 'RL incr *' falla o hace timeout (onError: 'continueErrorOutput'
// como propiedad del nodo), su output de error cae aca via 'Alertar admin - Fallo
// rate limiter (Redis)'. Reconstruye el item con el payload ORIGINAL de Telegram
// (leido por nombre de nodo, no por $json, porque $json en este punto puede traer
// el item de entrada del nodo Redis que fallo, no el payload completo) y lo deja
// pasar hacia 'Code in JavaScript7' como si estuviera dentro de cuota. Esta ruta es
// la UNICA excepcion fail-open de todo el change: los controles de firma binaria
// (grupo 1) y antivirus (grupo 3) siguen fail-closed sin excepcion.
return [{ json: $('Clasificar evento para rate limit').first().json }];

// Filtro heurístico injection en prompt libre (capability freetext-injection-gate, D5 apéndice)
// Rama: Generate an image (freetext-generate). Cheap deterministic pre-filter — cubre las
// técnicas con 100% de cumplimiento en la campaña (corrida #2, ver design.md D5 apéndice):
// persona_role_change, dev_admin_audit_impersonation, embedded_in_product_data. Si matchea,
// se marca sospechoso YA (se salta la llamada a Gemini, capa más barata primero, design.md D7).
// Lógica probada contra el banco real ANTES de escribir este nodo (tests/prompt-injection):
// 12/13 maliciosos freetext capturados, 0/6 falsos positivos sobre el set de control.
function normalizeText(s) {
  return String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

const CHEAP_FILTER_PATTERNS = [
  // persona_role_change
  { technica: 'persona_role_change', re: /\bactua(s)?\s+como\b/ },
  { technica: 'persona_role_change', re: /\ba partir de ahora\s+(sos|actua|eres|te convertis)\b/ },
  { technica: 'persona_role_change', re: /\bsos\s+(ahora\s+)?(un\s+)?asistente\b/ },
  { technica: 'persona_role_change', re: /\byou'?re\s+now\b/ },
  { technica: 'persona_role_change', re: /\byou\s+are\s+now\b/ },
  { technica: 'persona_role_change', re: /\byour\s+are\s+now\b/ }, // typo tolerado (asi lo especifico la tarea)
  { technica: 'persona_role_change', re: /\bact\s+as\b/ },
  { technica: 'persona_role_change', re: /\bllamado\s+dan\b/ },

  // dev_admin_audit_impersonation
  { technica: 'dev_admin_audit_impersonation', re: /\bmodo\s+desarrollador\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\bmodo\s+admin\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\bmodo\s+auditoria\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\bmodo\s+de\s+prueba\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\bdeveloper\s+mode\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\badmin\s+mode\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\baudit\s+mode\b/ },
  { technica: 'dev_admin_audit_impersonation', re: /\btest\s+mode\b/ },

  // meta-comentario dirigido al modelo/IA/sistema
  { technica: 'model_meta_commentary', re: /\bnota\s+para\s+el\s+modelo\b/ },
  { technica: 'model_meta_commentary', re: /\bpara\s+la\s+ia\b/ },
  { technica: 'model_meta_commentary', re: /\bsystem\s+prompt\b/ },
  { technica: 'model_meta_commentary', re: /\bprompt\s+de\s+sistema\b/ },
  { technica: 'model_meta_commentary', re: /\binstrucciones\s+de\s+sistema\b/ },
  { technica: 'model_meta_commentary', re: /\bsystem\s+instructions?\b/ },
  { technica: 'model_meta_commentary', re: /\bignora(s)?\s+las\s+instrucciones\b/ },
  { technica: 'model_meta_commentary', re: /\bignora\s+todas\s+las\s+instrucciones\b/ },
  { technica: 'model_meta_commentary', re: /\bignora\s+lo\s+anterior\b/ },
  { technica: 'model_meta_commentary', re: /\bignore\s+all\s+(prior|previous)\s+(\w+\s+)?instructions?\b/ },
];

function checkN8nCombo(norm) {
  if (!/\bn8n\b/.test(norm)) return null;
  if (/(modo|audit|prueba|equipo tecnico|nota del equipo)/.test(norm)) {
    return 'dev_admin_audit_impersonation';
  }
  return null;
}

function checkBracketMarker(norm) {
  const m = norm.match(/\[([^\]]{0,100})\]/);
  if (!m) return null;
  const inner = m[1];
  if (/(modo|sistema|interna|configuracion|auditoria|desarroll|admin|tecnico|actualizacion|config)/.test(inner)) {
    return 'bracket_marker';
  }
  return null;
}

function cheapFilterCheck(text) {
  const norm = normalizeText(text);
  for (const { technica, re } of CHEAP_FILTER_PATTERNS) {
    const match = norm.match(re);
    if (match) return { sospechoso: true, tecnica: technica, patron: match[0] };
  }
  const n8nCombo = checkN8nCombo(norm);
  if (n8nCombo) return { sospechoso: true, tecnica: n8nCombo, patron: 'n8n + vocabulario de modo/auditoria' };
  const bracket = checkBracketMarker(norm);
  if (bracket) return { sospechoso: true, tecnica: bracket, patron: 'marcador entre corchetes' };
  return { sospechoso: false, tecnica: null, patron: null };
}

const item = $input.first();
const idChat = $('Code in JavaScript5').first().json.id_chat;
const texto = item.json.text || '';
const resultado = cheapFilterCheck(texto);

return [{
  json: {
    ...item.json,
    injectionGate: {
      control: 'freetext_injection',
      rama: 'generate',
      idChat,
      limpio: !resultado.sospechoso,
      capa: resultado.sospechoso ? 'filtro_barato' : null,
      tecnica: resultado.tecnica,
      detalle: resultado.patron
