const original = $('Filtro heurístico injection - Generate').first().json;

function tryParseJson(text) {
  try { return JSON.parse(text.trim()); } catch (_) { /* sigue abajo */ }
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (_) { return null; }
}

const parsed = tryParseJson(rawText);
const detectado = (parsed && typeof parsed.prompt_injection_detectado === 'boolean')
  ? parsed.prompt_injection_detectado
  : true; // formato inesperado del clasificador = fail-closed (design.md D8), no "pasa igual"
const textoSospechoso = (parsed && typeof parsed.texto_sospechoso === 'string')
  ? parsed.texto_sospechoso.slice(0, 300)
  : null;

return [{
  json: {
    ...original,
    injectionGate: {
      ...original.injectionGate,
      limpio: !detectado,
      capa: detectado ? 'gemini' : null,
      tecnica: null,
      detalle: textoSospechoso
