const original = $('Filtro heurístico injection - Generate').first().json;
const errItem = $input.first().json || {};
const errorMsg = (errItem.error && errItem.error.message) || errItem.message || 'error desconocido en clasificador Gemini';

return [{
  json: {
    ...original,
    injectionGate: {
      ...original.injectionGate,
      limpio: false,
      capa: 'gemini_error',
      tecnica: null,
      detalle: String(errorMsg).slice(0, 300)
    }
