// Reconstruye el payload original (el nodo Gemini no pasa a través el json de entrada,
// solo devuelve la respuesta de la API) referenciando 'Filtro heurístico injection - Edit' — mismo patrón que
// 'Media rechazada - malware' (referencia cruzada al nodo anterior, no $json/.item directos).
const rawText = ($input.first().json.content && $input.first().json.content.parts && $input.first().json.content.parts[0] && $input.first().json.content.parts[0].text) || '';
const original = $('Filtro heurístico injection - Edit').first().json;
const originalBinary = $('Filtro heurístico injection - Edit').first().binary;

function tryParseJson(text) {
  try { return JSON.parse(text.trim()); } catch (_) { /* sigue abajo */ }
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (_) { return null; }
}

const parsed = tryParseJson(rawText);
const detectado = (parsed && typeof parsed.prompt_injection_detectado === 'boolean')
  ? parsed.prompt_injection_detectado
  : true; // formato inesperado del clasificador = fail-closed (design.md D8), no "pasa igual"
const textoSospechoso = (parsed && typeof parsed.texto_sospechoso === 'string')
  ? parsed.texto_sospechoso.slice(0, 300)
  : null;

return [{
  json: {
    ...original,
    injectionGate: {
      ...original.injectionGate,
      limpio: !detectado,
      capa: detectado ? 'gemini' : null,
      tecnica: null,
      detalle: textoSospechoso
    }
  },
  binary: originalBinary
}];

// Error output del clasificador Gemini (timeout/5xx/respuesta rota) -> fail-closed
// (design.md D8): se trata igual que una detección positiva, SIN excepción. Esta superficie
// NO tiene la excepción fail-open del rate limiter (D8 la acota exclusivamente a rate limit).
const original = $('Filtro heurístico injection - Edit').first().json;
const originalBinaryErr = $('Filtro heurístico injection - Edit').first().binary;
const errItem = $input.first().json || {};
const errorMsg = (errItem.error && errItem.error.message) || errItem.message || 'error desconocido en clasificador Gemini';

return [{
  json: {
    ...original,
    injectionGate: {
      ...original.injectionGate,
      limpio: false,
      capa: 'gemini_error',
      tecnica: null,
      detalle: String(errorMsg).slice(0, 300)
    }
  },
  binary: originalBinaryErr
}];

