      }
      if (primerIndex !== -1) encontradas.push({ canon, variants, index: primerIndex });
    }
    if (encontradas.length === 0) continue;

    encontradas.sort((a, b) => a.index - b.index);
    const necesitaNumerar = encontradas.length > 1;

    encontradas.forEach(({ canon, variants }, idx) => {
      const etiqueta = necesitaNumerar ? (descriptor + ' (opción ' + (idx + 1) + ')') : descriptor;
      for (const variant of variants) {
        result = result.replace(buildVariantPattern(variant), etiqueta);
