const original = $('Code in JavaScript5').first().json.dato || '';
const { textoFiltrado, marcasDetectadas } = replaceKnownBrands(original);

return [{
  json: {
    ...item.json,
    datoSinMarca: textoFiltrado,
    marcasFiltradas: marcasDetectadas
  },
  binary: item.binary
}];

parameters.text:
=Analizá la imagen adjunta, generada o editada por IA para una publicidad de redes sociales, y determiná si contiene el logo, isotipo, eslogan o diseño distintivo de una marca de terceros real y reconocible (por ejemplo, pero no limitado a: Nike, Adidas, Puma, Coca-Cola, Pepsi, McDonald's, Burger King, Apple, Samsung, Nintendo, Toyota, BMW — cualquier marca comercial identificable que NO sea la del negocio dueño del catálogo). Un producto genérico de ese rubro (ej: una zapatilla deportiva sin logo, una gaseosa sin marca) NO cuenta como marca detectada — solo marcá que sí hay marca si el logo, símbolo o texto de esa marca es visible e identificable en la imagen.

Responde EXCLUSIVAMENTE con este JSON, sin texto introductorio, sin explicaciones, sin fences de markdown, empezando con { y terminando con }:
{"marca_detectada": true o false (booleano), "marca": "nombre de la marca detectada, o null si no hay ninguna", "motivo": "motivo breve en español, máximo 140 caracteres"}

parameters.jsCode:
// brand-hardening: parsea el veredicto de 'Verificar marcas en imagen generada' y
// reconstruye el item (json + binary) desde quien haya corrido realmente
// ('Generate an image' o 'Edit an image' -- solo una de las dos corre por ejecución).
// Fail-closed (mismo criterio que el resto de los clasificadores del proyecto):
// cualquier respuesta con forma inesperada = marca_detectada true, no "pasa igual".
let rawText = '';
try { rawText = $input.first().json.content.parts[0].text; } catch (e) { rawText = ''; }

function tryParseJson(text) {
  const cleaned = String(text).replace(/```json|```/g, '').trim();
  try { return JSON.parse(cleaned); } catch (_) { /* sigue abajo */ }
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); } catch (_) { return null; }
}

const parsed = tryParseJson(rawText);
const detectada = (parsed && typeof parsed.marca_detectada === 'boolean') ? parsed.marca_detectada : true;
const marca = (parsed && typeof parsed.marca === 'string') ? parsed.marca : null;
const motivo = (parsed && typeof parsed.motivo === 'string') ? parsed.motivo : 'No se pudo verificar la imagen.';

let original;
try { original = $('Generate an image').first(); } catch (e) { original = null; }
if (!original || !original.binary) {
  try { original = $('Edit an image').first(); } catch (e) { original = null; }
}
if (!original) { original = { json: {}, binary: {} }; }

return [{
  json: {
    ...original.json,
    marcaImagenGate: { detectada, marca, motivo }
  },
  binary: original.binary
}];

// product-overwrite-safety (2026-08-23): adapta la salida de 'Code in JavaScript1'
// ({productos, prompt_injection_detectado, texto_sospechoso}) al formato {items}
// que consume el pipeline compartido de confirmación (mismo campo que las ramas
// Sheets/Imagen).
// partial-success (2026-08-23): se llega aca tanto si el IF dio true como
// false -- los productos se suben en ambos casos, la alerta al admin (si
// corresponde) ya se disparo en paralelo desde el propio IF.
return [{ json: { items: $json.productos || [] } }];

// product-overwrite-safety (2026-08-23): la rama Imagen extrae UN producto por foto.
// image-injection-gate (2026-08-23): se descartan los campos de metadata de
// injection (no son datos del producto, son señal interna ya consumida por
// "IF - Prompt injection detectado - Imagen") antes de armar el item que se
// sube al catalogo.
const { prompt_injection_detectado, texto_sospechoso, ...producto } = $json;
return [{ json: { items: [producto] } }];

// product-overwrite-safety (2026-08-23): arma el mensaje de confirmación a partir
// del diff_preview, y reconstruye 'items' (el propio diff_preview no los devuelve
// completos, solo un resumen) desde quien haya corrido de las 3 ramas -- solo una
// de las tres corre por ejecución, de ahí el try/catch en cadena (mismo patrón que
// 'Parsear veredicto marcas imagen').
let origen = null;
try { origen = $('Aggregate - Productos sheets pendientes').first().json; } catch (e) { origen = null; }
if (!origen) { try { origen = $('Preparar pendientes - PDF').first().json; } catch (e) { origen = null; } }
if (!origen) { try { origen = $('Preparar pendientes - Imagen').first().json; } catch (e) { origen = null; } }
const items = (origen && origen.items) || [];

const diff = $json || {};
const resumen = diff.resumen || { nuevos: 0, actualizados: 0, radicales: 0, total: items.length };
const itemsDiff = Array.isArray(diff.items) ? diff.items : [];
const radicales = itemsDiff.filter((it) => it.es_radical);

const panelUrl = String($env.AURA_FRONTEND_URL || '').replace(/\/$/, '') + '/productos';

let texto = `⚠️ *Vas a actualizar tu catálogo*\n\n`;
texto += `• ${resumen.nuevos || 0} producto(s) nuevo(s)\n`;
texto += `• ${resumen.actualizados || 0} producto(s) existente(s) van a actualizarse\n`;
if ((resumen.radicales || 0) > 0) {
  texto += `• ⚠️ ${resumen.radicales} con un cambio *radical* (precio o descripción muy distintos):\n`;
  for (const r of radicales.slice(0, 8)) {
    const motivos = Array.isArray(r.motivos) ? r.motivos.join(', ') : '';
    texto += `   - ${r.nombre || 'producto sin nombre'}: ${motivos}\n`;
  }
  if (radicales.length > 8) texto += `   ...y ${radicales.length - 8} más\n`;
}
texto += `\n¿Confirmás que querés guardar estos cambios?\n\n`;
texto += `Por seguridad, te recomendamos entrar a ${panelUrl} para verificar que todo se haya cargado bien. `;
texto += `Si algo salió mal, desde ahí podés volver a la versión anterior de cualquier producto.`;

return [{
  json: {
    items,
    resumen,
    mensaje_confirmacion: texto
  }
}];

// product-overwrite-safety (2026-08-23): parsea el array guardado en
// 'Redis - Guardar pendiente upsert'. Si esta vacío/expiró (TTL 24h), devuelve UN
// item marcador (_vacio) en vez de cero items, para que el flujo de abajo
// ('IF - Hay pendientes upsert') pueda saltar el upsert y limpiar/avisar igual --
// un array vacío haría que ningún nodo de acá en adelante corra, dejando el chat
// en 'ESPERANDO CONFIRMACION SOBRESCRITURA' para siempre.
let items = [];
try { items = JSON.parse($json.pendiente_upsert_raw || '[]'); } catch (e) { items = []; }
if (!Array.isArray(items) || items.length === 0) {
  return [{ json: { _vacio: true } }];
}
return items.map((item) => ({ json: item }));

// brand-hardening bugfix (2026-08-23): error output (index 1, onError:
// continueErrorOutput) de 'Verificar marcas en imagen generada'. Fail-closed
// (mismo criterio que el resto de los clasificadores del proyecto, ver
// 'Preparar rechazo - error Gemini - Generate'): cualquier error de la API
// Gemini (timeout/5xx/respuesta rota) se trata como marca detectada, nunca se
// deja pasar "por las dudas".
const errItem = $input.first().json || {};
const errorMsg = (errItem.error && errItem.error.message) || errItem.message || 'error desconocido al verificar la imagen';

// admin-debug (2026-08-23): preservamos el binario de la imagen (mismo
// patron que 'Parsear veredicto marcas imagen') para que la alerta al admin
// pueda adjuntarla tambien en este camino de error -- best effort, si no se
// encuentra queda vacio y la alerta sale sin foto (no bloquea el flujo).
let original;
try { original = $('Generate an image').first(); } catch (e) { original = null; }
if (!original || !original.binary) {
  try { original = $('Edit an image').first(); } catch (e) { original = null; }
}

return [{
  json: {
    marcaImagenGate: {
      detectada: true,
      marca: null,
      motivo: 'Error al verificar la imagen: ' + String(errorMsg).slice(0, 300)
    }
  },
  binary: original ? original.binary : {}
}];

// Compara las versiones vigentes de cada documento legal (legal_documents)
// contra lo que este usuario ya acepto por Telegram (legal_acceptances,
// channel='telegram'). Un documento cuenta como aceptado solo si existe fila
// Y su version coincide con la vigente (si la politica/terminos cambiaron
// despues de la ultima aceptacion, vuelve a pedirse).
const versionesItems = $('HTTP - Versiones legales').all().map(i => i.json).filter(v => v && v.slug);
const aceptacionesItems = $('HTTP - Aceptaciones legales telegram').all().map(i => i.json).filter(a => a && a.document);

const versiones = {};
for (const v of versionesItems) versiones[v.slug] = { version: v.version, url: v.url };

function estaAceptado(slug) {
  const fila = aceptacionesItems.find(a => a.document === slug);
  return !!fila && !!versiones[slug] && fila.version === versiones[slug].version;
}

const privacidadOk = estaAceptado('privacy_policy');
const terminosOk = estaAceptado('terms_conditions');

return [{
  json: {
    ambosAceptados: privacidadOk && terminosOk,
    privacidadOk,
    terminosOk,
    versiones: {
      privacy_policy: versiones.privacy_policy || { version: null, url: '' },
      terms_conditions: versiones.terms_conditions || { version: null, url: '' }
    }
  }
}];
